      "  --ui-font:13px/1.45 \"Segoe UI\", system-ui, sans-serif;\n}\n/* Marca Ruta (FLUYO-BRAND-RUTA-001, decisión 325; referencia: .ai/referencias/logo-ruta/). Símbolo + «fluyo» en la cabecera del\n   editor, del Viewer y de las páginas; el tamaño, la letra y el color (--ink) los pone cada cabecera. 24 px con la palabra a 21 px,\n   separados 8 px (codigo/logo-cabecera.html): en em, para que el par escale con la palabra. El trazo es currentColor y el envío\n   --attention: sin colores sueltos. .still es el símbolo fijo (svg/fluyo-simbolo.svg, exacto); .loop, la animación de la referencia,\n   tal cual. El bucle solo corre si el sistema no pide menos movimiento; cada cabecera vuelve a .still donde antes ocultaba los puntos. */\n.logo .logoMark{width:calc(24em / 21); height:calc(24em / 21); flex:none; overflow:hidden;}\n.logoMark circle{fill:var(--attention);}\n.logoMark .loop{display:none;}\n/* El sistema que avanza: el envío llega, aparece una caja nueva y la ruta se desplaza (4.8 s en bucle). Las animaciones solo se\n   declaran aquí: un <g> con display:none no para las de sus hijos en Chrome, y el bucle oculto seguiría recalculando cada fotograma. */\n@media (prefers-reduced-motion: no-preference){\n.logoMark .still{display:none;} .logoMark .loop{display:inline;}\n.logoMark .pan{animation:logoMark-pan 4.8s cubic-bezier(.45,0,.2,1) infinite}\n.logoMark .old{animation:logoMark-old 4.8s ease infinite}\n.logoMark .n2{transform-box:fill-box;transform-origin:center;animation:logoMark-n2 4.8s ease infinite}\n.logoMark .n3{transform-box:fill-box;transform-origin:center;opacity:0;animation:logoMark-n3 4.8s cubic-bezier(.2,0,0,1) infinite}\n.logoMark .r2{stroke-dasharray:52;stroke-dashoffset:52;animation:logoMark-r2 4.8s cubic-bezier(.45,0,.2,1) infinite}\n.logoMark .tok{offset-path:path(\"M22 16 H36 V48 H42\");offset-rotate:0deg;offset-distance:57.6923%;animation:logoMark-tok 4.8s infinite}\n}\n/* El envío descansa donde lo pinta el símbolo fijo (svg/fluyo-simbolo.svg, círculo en 36,32): 30 de los 52 de la ruta = 57,6923 %.\n   La referencia animada lo dejaba en el 50 % (36,28) y saltaba 4 unidades al pasar al fijo; manda el fijo (PO, FLUYO-BRAND-RUTA-001). */\n@keyframes logoMark-tok{0%{offset-distance:57.6923%;opacity:1;animation-timing-function:cubic-bezier(.45,0,.55,1)}17%{opacity:1}19%{offset-distance:100%;opacity:0}46%{offset-distance:0%;opacity:0;animation-timing-function:cubic-bezier(.45,0,.55,1)}49%{opacity:1}67%,100%{offset-distance:57.6923%;opacity:1}}\n@keyframes logoMark-pan{0%,23%{transform:translate(0,0)}48%,100%{transform:translate(-36px,-32px)}}\n@keyframes logoMark-old{0%,23%{opacity:1}38%,100%{opacity:0}}\n@keyframes logoMark-n2{0%,18%{fill-opacity:1;transform:scale(1)}20.5%{transform:scale(1.14)}23%{fill-opacity:1;transform:scale(1)}44%,100%{fill-opacity:0;transform:scale(1)}}\n@keyframes logoMark-n3{0%,26%{opacity:0;transform:scale(.4)}44%,100%{opacity:1;transform:scale(1)}}\n@keyframes logoMark-r2{0%,25%{stroke-dashoffset:52}45%,100%{stroke-dashoffset:0}}\n/* Fijo (aquí y en cada cabecera donde antes se ocultaban los puntos): .still a la vista y el bucle quieto, no solo oculto.\n   El teléfono en apaisado también es móvil (la gramática de FLUYO-018.19). */\n@media (orientation:landscape) and (max-height:500px) and (pointer:coarse){ .logo .logoMark .still{display:inline;} .logo .logoMark :is(.loop, .loop *){display:none; animation:none;} }\nbutton, select{\n  background:var(--panel2); color:var(--text); border:1px solid var(--line);",
